import importlib.util, random, itertools
spec=importlib.util.spec_from_file_location("m","/workspace/submission/main.py")
m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
def brute(queries,pids,sig):
    pairs=[]; 
    for i in range(len(pids)):
        for j in range(i+1,len(pids)): pairs.append((pids[i],pids[j]))
    univ=0; cov={}
    for q in queries:
        mask=0
        for k,(a,b) in enumerate(pairs):
            if sig[(q['id'],a)]!=sig[(q['id'],b)]: mask|=1<<k
        cov[q['id']]=mask; univ|=mask
    if univ==0: return (0,0)
    best=None; qs=[q['id'] for q in queries]; cost={q['id']:q['cost'] for q in queries}
    for combo in itertools.product([0,1],repeat=len(qs)):
        u=0;c=0;n=0
        for bit,qid in zip(combo,qs):
            if bit: u|=cov[qid]; c+=cost[qid]; n+=1
        if u==univ:
            key=(c,n)
            if best is None or key<best: best=key
    return best
rng=random.Random(3)
for trial in range(60):
    np=rng.randint(2,6); pids=[f"p{i}" for i in range(np)]
    nq=rng.randint(6,14)
    queries=[{'id':f"q{i}",'name':'x','type':'A','cost':rng.randint(1,10)} for i in range(nq)]
    sig={}
    for q in queries:
        for p in pids:
            sig[(q['id'],p)]=rng.randint(0,3)
    b=m.optimal_basis(queries,pids,sig)
    e=brute(queries,pids,sig)
    if (b[1],b[2])!=e:
        print("MISMATCH",trial,b,e); break
else: print("larger fuzz OK")
